{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "2 <= n <= 400000",
      "description": "The number of vertices in the tree is between 2 and 400,000."
    },
    {
      "id": "P2",
      "expression": "1 <= ui, vi <= n",
      "description": "Each edge connects two vertices within the range of 1 to n."
    },
    {
      "id": "P3",
      "expression": "The graph is a tree.",
      "description": "The graph is connected and contains no cycles."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output[i] == 1 if vertex i can be made a centroid by replacing no more than one edge, else 0",
      "description": "The output array contains binary indicators for each vertex."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "expression": "sum(output) <= n",
      "description": "The number of vertices that can be made centroids is at most n."
    }
  ]
}
